import type { Knowledge } from '../story-state';

export interface DialogueIntent {
  id: `q_${string}`; family: string; label: string; gate?: Knowledge; files: string[];
  examples: string[]; early: string; revealed: string; easterEgg: boolean;
}
// Each row is authored: label | reveal condition | sources | before | after | seven distinct phrasings.
// Recognition text never grants a permission or changes an operating state.
function family(name: string, text: string, easterEgg = false): DialogueIntent[] {
  return text.trim().split('\n').map(row => {
    const [id, gate, sources, early, revealed, examples] = row.split('|').map(s => s.trim());
    return { id: `q_${id}`, label: id.replaceAll('_', ' '), family: name, gate: gate === '-' ? undefined : gate as Knowledge, files: sources === '-' ? [] : sources.split(','), early, revealed, examples: examples.split('~'), easterEgg };
  });
}
